        /// The `PAD_COMP_CONFIG_0` register.
        ///
        /// Configuration register for zero-crossing detection
        pub mod pad_comp_config_0 {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0x0000001f;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0x58;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// Configures whether to enable the function of analog PAD voltage comparator.\\ 0: Disable\\ 1: Enable\\
                #[inline]
                pub const fn xpd_comp_0(self) -> bool {
                    (self.0 & 0x00000001) != 0
                }

                /// Configures the reference voltage for analog PAD voltage comparater.. \\ 0: Reference voltage is the internal reference voltage, meanwhile GPIO8 PAD can be used as a regular GPIO\\ 1: Reference voltage is the voltage on the GPIO8 PAD\\
                #[inline]
                pub const fn mode_comp_0(self) -> bool {
                    (self.0 & 0x00000002) != 0
                }

                /// Configures the internal reference voltage for analog PAD voltage coparator. \\ 0: Internal reference voltage is 0 * VDDPST1\\ 1: Internal reference voltage is 0.1 * VDDPST1\\ …...\\ 6: Internal reference voltage is 0.6 * VDDPST1\\ 7: Internal reference voltage is 0.7 * VDDPST1\\
                #[inline]
                pub const fn dref_comp_0(self) -> oer_mmio::Bits<3> {
                    oer_mmio::Bits::truncate(self.0 >> 2)
                }
            }
        }

