            pub fn read_st(&self) -> st::R {
                st::R(self.0.read::<0x24>())
            }

            /// Read `INT_ENA`.
            #[inline]
            pub fn read_int_ena(&self) -> int_ena::R {
                int_ena::R(self.0.read::<0x28>())
            }

            /// Read `INT_RAW`.
