            pub fn read_int_raw(&self) -> int_raw::R {
                int_raw::R(self.0.read::<0x2c>())
            }

            /// Read `INT_ST`.
            #[inline]
            pub fn read_int_st(&self) -> int_st::R {
                int_st::R(self.0.read::<0x30>())
            }

            /// Read `RX_ST0`.
            #[inline]
            pub fn read_rx_st0(&self) -> rx_st0::R {
                rx_st0::R(self.0.read::<0x38>())
            }

            /// Read `RX_ST1`.
            #[inline]
            pub fn read_rx_st1(&self) -> rx_st1::R {
                rx_st1::R(self.0.read::<0x3c>())
            }

