        /// The `RX_MODE_CFG` register.
        ///
        /// Parallel RX Sampling mode configuration register.
        pub mod rx_mode_cfg {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0xffe00000;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0x0;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// Configures rx external enable signal selection from IO PAD.
                #[inline]
                pub const fn rx_ext_en_sel(self) -> oer_mmio::Bits<4> {
                    oer_mmio::Bits::truncate(self.0 >> 21)
                }

                /// Write 1 to enable data sampling by software.
                #[inline]
                pub const fn rx_sw_en(self) -> bool {
                    (self.0 & 0x02000000) != 0
                }

                /// Write 1 to invert the external enable signal.
                #[inline]
                pub const fn rx_ext_en_inv(self) -> bool {
                    (self.0 & 0x04000000) != 0
                }

                /// Configures the rxd pulse sampling submode. 0: positive pulse start(data bit included) && positive pulse end(data bit included) 1: positive pulse start(data bit included) && positive pulse end (data bit excluded) 2: positive pulse start(data bit excluded) && positive pulse end (data bit included) 3: positive pulse start(data bit excluded) && positive pulse end (data bit excluded) 4: positive pulse start(data bit included) && length end 5: positive pulse start(data bit excluded) && length end
                #[inline]
                pub const fn rx_pulse_submode_sel(self) -> oer_mmio::Bits<3> {
                    oer_mmio::Bits::truncate(self.0 >> 27)
                }

                /// Configures the rxd sampling mode. 0: external level enable mode 1: external pulse enable mode 2: internal software enable mode
                #[inline]
                pub const fn rx_smp_mode_sel(self) -> oer_mmio::Bits<2> {
                    oer_mmio::Bits::truncate(self.0 >> 30)
                }
            }
        }

