        /// The `U%s_STATUS` register.
        ///
        /// PNCT UNIT%s status register
        pub mod u_status {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0x000001ff;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0x60;

            /// The byte distance between two elements of the array.
            pub const STRIDE: usize = 0x4;
            /// The array's element count.
            pub const COUNT: usize = 4;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// Represents the pulse counter status of PCNT_U%s corresponding to 0. \\ 0: pulse counter decreases from positive to 0\\ 1: pulse counter increases from negative to 0\\ 2: pulse counter is negative\\ 3: pulse counter is positive \\
                #[inline]
                pub const fn cnt_thr_zero_mode_u(self) -> oer_mmio::Bits<2> {
                    oer_mmio::Bits::truncate(self.0)
                }

                /// Represents the latched value of thres1 event of PCNT_U%s when threshold event interrupt is valid. \\ 0: others\\ 1: the current pulse counter equals to thres1 and thres1 event is valid \\
                #[inline]
                pub const fn cnt_thr_thres1_lat_u(self) -> bool {
                    (self.0 & 0x00000004) != 0
                }

                /// Represents the latched value of thres0 event of PCNT_U%s when threshold event interrupt is valid. \\ 0: others\\ 1: the current pulse counter equals to thres0 and thres0 event is valid \\
                #[inline]
                pub const fn cnt_thr_thres0_lat_u(self) -> bool {
                    (self.0 & 0x00000008) != 0
                }

                /// Represents the latched value of low limit event of PCNT_U%s when threshold event interrupt is valid. \\ 0: others\\ 1: the current pulse counter equals to thr_l_lim and low limit event is valid. \\
                #[inline]
                pub const fn cnt_thr_l_lim_lat_u(self) -> bool {
                    (self.0 & 0x00000010) != 0
                }

                /// Represents the latched value of high limit event of PCNT_U%s when threshold event interrupt is valid. \\ 0: others\\ 1: the current pulse counter equals to thr_h_lim and high limit event is valid. \\
                #[inline]
                pub const fn cnt_thr_h_lim_lat_u(self) -> bool {
                    (self.0 & 0x00000020) != 0
                }

                /// Represents the latched value of zero threshold event of PCNT_U%s when threshold event interrupt is valid. \\ 0: others\\ 1: the current pulse counter equals to 0 and zero threshold event is valid. \\
                #[inline]
                pub const fn cnt_thr_zero_lat_u(self) -> bool {
                    (self.0 & 0x00000040) != 0
                }

                /// The latched value of step counter limit event of PCNT_U%s when step counter event interrupt is valid. 1: the current pulse counter equals to reg_cnt_step_lim and step counter event is valid. 0: others
                #[inline]
                pub const fn cnt_thr_step_lim_lat_u(self) -> bool {
                    (self.0 & 0x00000080) != 0
                }

                /// The latched value of step counter event of PCNT_U%s when step counter event interrupt is valid. 1: the current pulse counter increment equals to reg_cnt_step and step counter event is valid. 0: others
                #[inline]
                pub const fn cnt_thr_step_lat_u(self) -> bool {
                    (self.0 & 0x00000100) != 0
                }
            }
        }

