        /// The `T0CONFIG` register.
        ///
        /// Timer 0 configuration register
        pub mod t0config {
            /// The bits of the register's declared fields.
            pub const FIELDS: u32 = 0xffffe600;
            /// The register's byte offset in its block.
            pub const OFFSET: usize = 0x0;

            /// One observation of the register.
            #[derive(Clone, Copy, Debug, Eq, PartialEq)]
            pub struct R(pub(super) u32);

            impl R {
                /// 1: Use XTAL_CLK as the source clock of timer group. 0: Use APB_CLK as the source clock of timer group.
                #[inline]
                pub const fn t0_use_xtal(self) -> bool {
                    (self.0 & 0x00000200) != 0
                }

                /// Configures whether or not to enable the timer 0 alarm function. This bit will be automatically cleared once an alarm occurs.\\ 0: Disable \\ 1: Enable \\
                #[inline]
                pub const fn t0_alarm_en(self) -> bool {
                    (self.0 & 0x00000400) != 0
                }

                /// Represents the timer 0 clock (T0_clk) prescaler value.
                #[inline]
                pub const fn t0_divider(self) -> u16 {
                    (self.0 >> 13) as u16
                }

                /// Configures whether or not to enable the timer 0 auto-reload function at the time of alarm. \\ 0: No effect \\ 1: Enable \\
                #[inline]
                pub const fn t0_autoreload(self) -> bool {
                    (self.0 & 0x20000000) != 0
                }

                /// Configures the counting direction of the timer 0 time-base counter. \\ 0: Decrement \\ 1: Increment \\
                #[inline]
                pub const fn t0_increase(self) -> bool {
                    (self.0 & 0x40000000) != 0
                }

                /// Configures whether or not to enable the timer 0 time-base counter. \\ 0: Disable \\ 1: Enable \\
                #[inline]
                pub const fn t0_en(self) -> bool {
                    (self.0 & 0x80000000) != 0
                }
            }
        }

