                pub const fn resync_prolonged(self) -> oer_mmio::Bits<24> {
                    oer_mmio::Bits::truncate(self.0)
                }

                /// Configures the synchronization mode: \\0: Disable the synchronization counter \\1: Invalid \\2: Synchronization counter counts by packet \\3: Synchronization counter counts by cycle\\
                #[inline]
