                #[inline]
                pub const fn tx6s(self) -> oer_mmio::Bits<4> {
                    oer_mmio::Bits::truncate(self.0 >> 20)
                }

                /// Status of TXT buffer 7. Bit field meaning is analogous to TX1S.
                #[inline]
